__NUXT_JSONP__("/ru/how-to-apply", {data:[{details:{slug:"ru",pageTitle:"На какой вид визы вы планируете подать заявку? | Mentor Language Institute",pageDescription:"Выберите один из вариантов ниже",title:"На какой вид визы вы планируете подать заявку?",image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa.jpg",category:[{title:"Выберите один из вариантов ниже:",btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa_btn-ru.png",link:"\u002Fru\u002Fhow-to-apply\u002Fstudent-visa-f1"},btn_others:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fothers_btn-ru.png",link:"\u002Fru\u002Fhow-to-apply\u002Fothers"}}],content:{subtitle:"Есть вопросы?",description:["Как правило, вам понадобится студенческая виза для пребывания в Соединенных Штатах в качестве долгосрочного студента.","Если вы не знаете, нужна ли вам виза или нет, свяжитесь с нами.","Наши сотрудники говорят на 8 разных языках."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-ru.jpg",link:"\u002Fru\u002Fcontact"}},dir:"\u002Fhow-to-apply",path:"\u002Fhow-to-apply\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:29.648Z",updatedAt:"2025-05-26T12:06:27.790Z"}}],fetch:{},mutations:void 0});